INSERT INTO home_news_item (id, lang, title, excerpt, image_url, path, category, published_at) VALUES ('315b8c6e-59d1-23d6-510e-827e26cd9922', 'fr', 'Publication du Livre blanc de l’OEI', 'L''Observatoire publie son premier livre blanc, qui pose les fondations éthiques et professionnelles du métier d''informaticien.', '/assets/news/livre-blanc.svg', '/ressources', 'livre-blanc', '2026-07-15');
INSERT INTO home_news_item (id, lang, title, excerpt, image_url, path, category, published_at) VALUES ('a115cdb1-f991-3afd-b86e-7ad75f4c86e0', 'fr', 'Lancement du site public de l’OEI', 'Le site de l''Observatoire des Experts Informaticiens ouvre ses portes pour présenter la mission, les domaines d''action et l''espace membre.', '/assets/news/lancement-site.svg', '/a-propos', 'evenement', '2026-07-28');
INSERT INTO home_news_item (id, lang, title, excerpt, image_url, path, category, published_at) VALUES ('930ec294-648c-cbf4-8555-0a58042e8aa9', 'fr', 'Appel à contribution : rejoignez les groupes de travail thématiques', 'L''OEI invite les professionnels du numérique à contribuer aux groupes de travail sur la cybersécurité, l''IA, l''informatique verte et les autres domaines d''action.', '/assets/news/appel-contribution.svg', '/nos-missions', 'appel-a-contribution', '2026-08-01');
INSERT INTO home_news_item (id, lang, title, excerpt, image_url, path, category, published_at) VALUES ('80cb6b94-7221-af39-a89d-ccd845ff3ec4', 'en', 'Publication of the OEI White Paper', 'The Observatory publishes its first white paper, laying out the ethical and professional foundations of the IT profession.', '/assets/news/livre-blanc.svg', '/ressources', 'livre-blanc', '2026-07-15');
INSERT INTO home_news_item (id, lang, title, excerpt, image_url, path, category, published_at) VALUES ('8daf64e0-fb27-901a-341d-2c87a057a5e2', 'en', 'Launch of the OEI public website', 'The Observatoire des Experts Informaticiens website goes live, presenting the mission, action domains and the member area.', '/assets/news/lancement-site.svg', '/a-propos', 'evenement', '2026-07-28');
INSERT INTO home_news_item (id, lang, title, excerpt, image_url, path, category, published_at) VALUES ('067ba8f8-0330-159d-8c60-4362e0ed7cf5', 'en', 'Call for contributions: join our thematic working groups', 'The OEI invites IT professionals to contribute to working groups on cybersecurity, AI, green IT and the other action domains.', '/assets/news/appel-contribution.svg', '/nos-missions', 'appel-a-contribution', '2026-08-01');
INSERT INTO home_news_item (id, lang, title, excerpt, image_url, path, category, published_at) VALUES ('0ac70fbf-1e98-b27c-2226-524045bc94f1', 'de', 'Veröffentlichung des OEI-Weißbuchs', 'Das Observatorium veröffentlicht sein erstes Weißbuch, das die ethischen und beruflichen Grundlagen des IT-Berufs darlegt.', '/assets/news/livre-blanc.svg', '/ressources', 'livre-blanc', '2026-07-15');
INSERT INTO home_news_item (id, lang, title, excerpt, image_url, path, category, published_at) VALUES ('f547b4f4-3cb8-029a-5860-462c162492d4', 'de', 'Start der öffentlichen Website des OEI', 'Die Website des Observatoire des Experts Informaticiens geht online und stellt die Mission, die Handlungsfelder und den Mitgliederbereich vor.', '/assets/news/lancement-site.svg', '/a-propos', 'evenement', '2026-07-28');
INSERT INTO home_news_item (id, lang, title, excerpt, image_url, path, category, published_at) VALUES ('f25bb050-8205-babf-1c5a-35cb2c5bfa99', 'de', 'Aufruf zur Mitarbeit: Treten Sie unseren thematischen Arbeitsgruppen bei', 'Das OEI lädt IT-Fachleute ein, sich an Arbeitsgruppen zu Cybersicherheit, KI, grüner IT und den weiteren Handlungsfeldern zu beteiligen.', '/assets/news/appel-contribution.svg', '/nos-missions', 'appel-a-contribution', '2026-08-01');
INSERT INTO home_news_item (id, lang, title, excerpt, image_url, path, category, published_at) VALUES ('62c487ea-1a33-ae48-2e25-b538d44344dc', 'es', 'Publicación del Libro Blanco del OEI', 'El Observatorio publica su primer libro blanco, que sienta las bases éticas y profesionales de la profesión informática.', '/assets/news/livre-blanc.svg', '/ressources', 'livre-blanc', '2026-07-15');
INSERT INTO home_news_item (id, lang, title, excerpt, image_url, path, category, published_at) VALUES ('c4ded064-5205-b85a-6fd7-66bbc6ff73ba', 'es', 'Lanzamiento del sitio público del OEI', 'El sitio del Observatoire des Experts Informaticiens entra en línea, presentando la misión, los ámbitos de acción y el espacio de miembros.', '/assets/news/lancement-site.svg', '/a-propos', 'evenement', '2026-07-28');
INSERT INTO home_news_item (id, lang, title, excerpt, image_url, path, category, published_at) VALUES ('2e420f43-5c53-0129-03fb-7c22b6d0dbdd', 'es', 'Convocatoria de contribuciones: únase a nuestros grupos de trabajo temáticos', 'El OEI invita a los profesionales de la informática a contribuir en los grupos de trabajo sobre ciberseguridad, IA, informática verde y los demás ámbitos de acción.', '/assets/news/appel-contribution.svg', '/nos-missions', 'appel-a-contribution', '2026-08-01');
INSERT INTO home_news_item (id, lang, title, excerpt, image_url, path, category, published_at) VALUES ('04951c65-d0e5-9914-6915-ab5479b31a49', 'it', 'Pubblicazione del Libro Bianco dell''OEI', 'L''Osservatorio pubblica il suo primo libro bianco, che pone le basi etiche e professionali della professione informatica.', '/assets/news/livre-blanc.svg', '/ressources', 'livre-blanc', '2026-07-15');
INSERT INTO home_news_item (id, lang, title, excerpt, image_url, path, category, published_at) VALUES ('60a513cb-3187-5350-fe31-cb4b54fdf496', 'it', 'Lancio del sito pubblico dell''OEI', 'Il sito dell''Observatoire des Experts Informaticiens va online, presentando la missione, gli ambiti d''azione e l''area riservata ai membri.', '/assets/news/lancement-site.svg', '/a-propos', 'evenement', '2026-07-28');
INSERT INTO home_news_item (id, lang, title, excerpt, image_url, path, category, published_at) VALUES ('456dce1b-f1e8-f3e2-2192-179b1908c889', 'it', 'Invito a contribuire: unisciti ai nostri gruppi di lavoro tematici', 'L''OEI invita i professionisti IT a contribuire ai gruppi di lavoro su cybersicurezza, IA, informatica verde e gli altri ambiti d''azione.', '/assets/news/appel-contribution.svg', '/nos-missions', 'appel-a-contribution', '2026-08-01');
INSERT INTO home_news_item (id, lang, title, excerpt, image_url, path, category, published_at) VALUES ('971c68dc-ed4f-2fee-f73e-3585c16043e9', 'pt', 'Publicação do Livro Branco do OEI', 'O Observatório publica o seu primeiro livro branco, que estabelece as bases éticas e profissionais da profissão de informática.', '/assets/news/livre-blanc.svg', '/ressources', 'livre-blanc', '2026-07-15');
INSERT INTO home_news_item (id, lang, title, excerpt, image_url, path, category, published_at) VALUES ('64777cfe-d024-47c2-a055-47d8bf102be9', 'pt', 'Lançamento do site público do OEI', 'O site do Observatoire des Experts Informaticiens entra no ar, apresentando a missão, os domínios de ação e a área de membros.', '/assets/news/lancement-site.svg', '/a-propos', 'evenement', '2026-07-28');
INSERT INTO home_news_item (id, lang, title, excerpt, image_url, path, category, published_at) VALUES ('79a73ca7-8c5c-0fdd-2f1a-384b7edb060c', 'pt', 'Chamada de contribuições: junte-se aos nossos grupos de trabalho temáticos', 'O OEI convida os profissionais de TI a contribuírem para os grupos de trabalho sobre cibersegurança, IA, TI verde e os demais domínios de ação.', '/assets/news/appel-contribution.svg', '/nos-missions', 'appel-a-contribution', '2026-08-01');
