CREATE TABLE IF NOT EXISTS home_domain_area_detail (
    id uuid PRIMARY KEY,
    lang varchar(10) NOT NULL,
    slug varchar(255) NOT NULL,
    subtitle text,
    sections_json jsonb NOT NULL,
    related_resources_json jsonb NOT NULL,
    related_news_json jsonb NOT NULL,
    is_content_fallback boolean,
    CONSTRAINT uk_home_domain_area_detail_lang_slug UNIQUE (lang, slug)
);

UPDATE home_domain_area SET slug = COALESCE(slug, 'legacy-' || id::text), last_modified = COALESCE(last_modified, CURRENT_DATE);
UPDATE home_partner SET external_id = COALESCE(external_id, id::text);

